INSERT INTO public.ui_translations (key, lang, value) VALUES
  ('home.usp2_title', 'pl', 'Rodzic decyduje'),
  ('home.usp2_title', 'en', 'The parent decides'),
  ('home.usp2_title', 'de', 'Die Eltern entscheiden'),
  ('home.usp2_title', 'it', 'Decide il genitore'),
  ('home.usp2_title', 'fr', 'Le parent décide'),
  ('home.usp2_title', 'es', 'Deciden los padres'),
  ('home.usp2_title', 'pt', 'Os pais decidem'),
  ('home.usp2_title', 'nl', 'De ouder beslist'),
  ('home.usp2_title', 'cs', 'Rozhoduje rodič'),
  ('home.usp2_title', 'sk', 'Rozhoduje rodič'),
  ('home.usp2_title', 'hr', 'Odlučuje roditelj'),
  ('home.usp2_title', 'hu', 'A szülő dönt'),
  ('home.usp2_title', 'ro', 'Decide părintele'),
  ('home.usp2_title', 'sv', 'Föräldern bestämmer'),
  ('home.usp2_title', 'da', 'Forælderen bestemmer'),
  ('home.usp2_title', 'no', 'Forelderen bestemmer'),
  ('home.usp2_title', 'uk', 'Вирішують батьки'),
  ('home.usp2_text', 'pl', 'Dostajesz gotowy plan dnia z godzinami. Ostateczny kształt wycieczki ustalasz Ty: kiedy ruszyć, co pominąć i gdzie zostać dłużej.'),
  ('home.usp2_text', 'en', 'You get a ready-made day plan with times. You shape the final trip: when to set off, what to skip and where to stay longer.'),
  ('home.usp2_text', 'de', 'Du bekommst einen fertigen Tagesplan mit Uhrzeiten. Die endgültige Form bestimmst du: wann ihr losgeht, was ihr auslasst und wo ihr länger bleibt.'),
  ('home.usp2_text', 'it', 'Ricevi un piano della giornata già pronto, con gli orari. La forma finale la decidi tu: quando partire, cosa saltare e dove fermarvi più a lungo.'),
  ('home.usp2_text', 'fr', 'Vous recevez un plan de journée prêt, avec les horaires. C''est vous qui décidez de la forme finale : quand partir, quoi sauter et où rester plus longtemps.'),
  ('home.usp2_text', 'es', 'Recibes un plan del día listo, con horarios. La forma final la decides tú: cuándo salir, qué saltarte y dónde quedaros más tiempo.'),
  ('home.usp2_text', 'pt', 'Recebe um plano do dia pronto, com horários. A forma final é decisão sua: quando partir, o que saltar e onde ficar mais tempo.'),
  ('home.usp2_text', 'nl', 'Je krijgt een kant-en-klaar dagplan met tijden. De uiteindelijke vorm bepaal jij: wanneer je vertrekt, wat je overslaat en waar je langer blijft.'),
  ('home.usp2_text', 'cs', 'Dostanete hotový plán dne s časy. Konečnou podobu výletu určujete vy: kdy vyrazit, co vynechat a kde zůstat déle.'),
  ('home.usp2_text', 'sk', 'Dostanete hotový plán dňa s časmi. Konečnú podobu výletu určujete vy: kedy vyraziť, čo vynechať a kde zostať dlhšie.'),
  ('home.usp2_text', 'hr', 'Dobivate gotov plan dana s vremenima. Konačan oblik izleta određujete vi: kada krenuti, što preskočiti i gdje ostati dulje.'),
  ('home.usp2_text', 'hu', 'Kész napi tervet kapsz időpontokkal. A kirándulás végső formáját te döntöd el: mikor induljatok, mit hagyjatok ki, és hol maradjatok tovább.'),
  ('home.usp2_text', 'ro', 'Primești un plan al zilei gata făcut, cu ore. Forma finală o decizi tu: când porniți, ce săriți și unde stați mai mult.'),
  ('home.usp2_text', 'sv', 'Du får en färdig dagsplan med tider. Den slutliga formen bestämmer du: när ni ger er av, vad ni hoppar över och var ni stannar längre.'),
  ('home.usp2_text', 'da', 'Du får en færdig dagsplan med tidspunkter. Den endelige form bestemmer du: hvornår I tager af sted, hvad I springer over, og hvor I bliver længere.'),
  ('home.usp2_text', 'no', 'Du får en ferdig dagsplan med klokkeslett. Den endelige formen bestemmer du: når dere drar, hva dere hopper over og hvor dere blir lenger.'),
  ('home.usp2_text', 'uk', 'Ви отримуєте готовий план дня з часом. Остаточну форму поїздки визначаєте ви: коли вирушати, що пропустити і де залишитися довше.'),
  ('home.about_h2', 'pl', 'Rodzinne przewodniki po miastach Europy: od parkingu po ostatnią misję'),
  ('home.about_h2', 'en', 'Family city guides across Europe: from the car park to the last mission'),
  ('home.about_h2', 'de', 'Familien-Stadtführer durch Europa: vom Parkplatz bis zur letzten Mission'),
  ('home.about_h2', 'it', 'Guide familiari per le città d''Europa: dal parcheggio all''ultima missione'),
  ('home.about_h2', 'fr', 'Guides de villes en famille à travers l''Europe : du parking à la dernière mission'),
  ('home.about_h2', 'es', 'Guías familiares de ciudades de Europa: del aparcamiento a la última misión'),
  ('home.about_h2', 'pt', 'Guias de cidades europeias para famílias: do estacionamento à última missão'),
  ('home.about_h2', 'nl', 'Gezinsgidsen voor Europese steden: van de parkeerplaats tot de laatste missie'),
  ('home.about_h2', 'cs', 'Rodinní průvodci po evropských městech: od parkoviště po poslední misi'),
  ('home.about_h2', 'sk', 'Rodinní sprievodcovia po európskych mestách: od parkoviska po poslednú misiu'),
  ('home.about_h2', 'hr', 'Obiteljski vodiči po europskim gradovima: od parkirališta do posljednje misije'),
  ('home.about_h2', 'hu', 'Családi városkalauzok Európában: a parkolótól az utolsó küldetésig'),
  ('home.about_h2', 'ro', 'Ghiduri de oraș pentru familii prin Europa: de la parcare până la ultima misiune'),
  ('home.about_h2', 'sv', 'Familjeguider till Europas städer: från parkeringen till sista uppdraget'),
  ('home.about_h2', 'da', 'Familieguider til Europas byer: fra parkeringspladsen til den sidste mission'),
  ('home.about_h2', 'no', 'Familieguider til Europas byer: fra parkeringsplassen til det siste oppdraget'),
  ('home.about_h2', 'uk', 'Сімейні путівники містами Європи: від парковки до останньої місії'),
  ('home.about_p1', 'pl', 'Quolino to gotowe plany wycieczek jednodniowych dla rodzin z dziećmi, podróżujących autem po Europie. Każde miasto rozpisane godzina po godzinie: gdzie zaparkować, co zobaczyć i ile kosztują bilety.'),
  ('home.about_p1', 'en', 'Quolino offers ready-made day-trip plans for families with kids travelling by car across Europe. Every city is laid out hour by hour: where to park, what to see and how much tickets cost.'),
  ('home.about_p1', 'de', 'Quolino bietet fertige Tagesausflugspläne für Familien mit Kindern, die mit dem Auto durch Europa reisen. Jede Stadt ist Stunde für Stunde geplant: wo man parkt, was man sieht und was die Eintrittskarten kosten.'),
  ('home.about_p1', 'it', 'Quolino offre piani pronti per gite giornaliere per famiglie con bambini che viaggiano in auto per l''Europa. Ogni città è organizzata ora per ora: dove parcheggiare, cosa vedere e quanto costano i biglietti.'),
  ('home.about_p1', 'fr', 'Quolino propose des plans d''excursion d''une journée prêts à l''emploi pour les familles avec enfants qui voyagent en voiture en Europe. Chaque ville est organisée heure par heure : où se garer, que voir et combien coûtent les billets.'),
  ('home.about_p1', 'es', 'Quolino ofrece planes de excursión de un día listos para familias con niños que viajan en coche por Europa. Cada ciudad está organizada hora a hora: dónde aparcar, qué ver y cuánto cuestan las entradas.'),
  ('home.about_p1', 'pt', 'O Quolino oferece planos prontos de passeios de um dia para famílias com crianças que viajam de carro pela Europa. Cada cidade está organizada hora a hora: onde estacionar, o que ver e quanto custam os bilhetes.'),
  ('home.about_p1', 'nl', 'Quolino biedt kant-en-klare dagtochtplannen voor gezinnen met kinderen die met de auto door Europa reizen. Elke stad is uur voor uur uitgewerkt: waar je parkeert, wat je ziet en wat de tickets kosten.'),
  ('home.about_p1', 'cs', 'Quolino nabízí hotové plány jednodenních výletů pro rodiny s dětmi, které cestují po Evropě autem. Každé město je rozepsané hodinu po hodině: kde zaparkovat, co vidět a kolik stojí vstupenky.'),
  ('home.about_p1', 'sk', 'Quolino ponúka hotové plány jednodňových výletov pre rodiny s deťmi, ktoré cestujú po Európe autom. Každé mesto je rozpísané hodinu po hodine: kde zaparkovať, čo vidieť a koľko stoja vstupenky.'),
  ('home.about_p1', 'hr', 'Quolino nudi gotove planove jednodnevnih izleta za obitelji s djecom koje putuju automobilom po Europi. Svaki grad razrađen je sat po sat: gdje parkirati, što vidjeti i koliko stoje ulaznice.'),
  ('home.about_p1', 'hu', 'A Quolino kész egynapos kirándulási terveket kínál gyerekes családoknak, akik autóval utaznak Európában. Minden város óráról órára ki van dolgozva: hol parkolj, mit nézz meg, és mennyibe kerülnek a jegyek.'),
  ('home.about_p1', 'ro', 'Quolino oferă planuri gata făcute de excursii de o zi pentru familiile cu copii care călătoresc cu mașina prin Europa. Fiecare oraș este organizat oră cu oră: unde parchezi, ce vezi și cât costă biletele.'),
  ('home.about_p1', 'sv', 'Quolino erbjuder färdiga planer för dagsutflykter för barnfamiljer som reser med bil i Europa. Varje stad är planerad timme för timme: var ni parkerar, vad ni ser och vad biljetterna kostar.'),
  ('home.about_p1', 'da', 'Quolino tilbyder færdige planer for endagsture til børnefamilier, der rejser i bil i Europa. Hver by er planlagt time for time: hvor I parkerer, hvad I skal se, og hvad billetterne koster.'),
  ('home.about_p1', 'no', 'Quolino tilbyr ferdige planer for dagsturer for barnefamilier som reiser med bil i Europa. Hver by er planlagt time for time: hvor dere parkerer, hva dere ser og hva billettene koster.'),
  ('home.about_p1', 'uk', 'Quolino пропонує готові плани одноденних поїздок для сімей з дітьми, які подорожують Європою автомобілем. Кожне місто розписане година за годиною: де припаркуватися, що подивитися і скільки коштують квитки.'),
  ('home.about_p3', 'pl', 'Rodzic decyduje o ostatecznym kształcie wycieczki. Plan podpowiada kolejność przystanków i czas zwiedzania, a Ty wybierasz porę startu, wyłączasz przystanki, które dziś pomijacie, i zostajecie dłużej tam, gdzie dzieciom się podoba.'),
  ('home.about_p3', 'en', 'The parent decides the final shape of the trip. The plan suggests the order of stops and the visiting time; you choose when to start, switch off the stops you are skipping today and stay longer wherever the kids are having fun.'),
  ('home.about_p3', 'de', 'Die Eltern entscheiden über die endgültige Form des Ausflugs. Der Plan schlägt die Reihenfolge der Stationen und die Besichtigungszeit vor; ihr wählt die Startzeit, schaltet Stationen ab, die ihr heute auslasst, und bleibt länger, wo es den Kindern gefällt.'),
  ('home.about_p3', 'it', 'È il genitore a decidere la forma finale della gita. Il piano suggerisce l''ordine delle tappe e il tempo di visita; tu scegli quando partire, disattivi le tappe che oggi saltate e restate più a lungo dove i bambini si divertono.'),
  ('home.about_p3', 'fr', 'C''est le parent qui décide de la forme finale de la sortie. Le plan propose l''ordre des étapes et la durée de visite ; vous choisissez l''heure de départ, désactivez les étapes que vous sautez aujourd''hui et restez plus longtemps là où les enfants s''amusent.'),
  ('home.about_p3', 'es', 'Los padres deciden la forma final de la excursión. El plan sugiere el orden de las paradas y el tiempo de visita; tú eliges cuándo empezar, desactivas las paradas que hoy os saltáis y os quedáis más tiempo donde los niños se lo pasan bien.'),
  ('home.about_p3', 'pt', 'Os pais decidem a forma final do passeio. O plano sugere a ordem das paragens e o tempo de visita; você escolhe quando começar, desativa as paragens que hoje vão saltar e ficam mais tempo onde as crianças se divertem.'),
  ('home.about_p3', 'nl', 'De ouder bepaalt de uiteindelijke vorm van de uitstap. Het plan stelt de volgorde van de stops en de bezoektijd voor; jij kiest wanneer je begint, zet stops uit die jullie vandaag overslaan en blijft langer waar de kinderen plezier hebben.'),
  ('home.about_p3', 'cs', 'O konečné podobě výletu rozhoduje rodič. Plán navrhuje pořadí zastávek a dobu prohlídky; vy volíte, kdy vyrazit, vypnete zastávky, které dnes vynecháte, a zůstanete déle tam, kde se dětem líbí.'),
  ('home.about_p3', 'sk', 'O konečnej podobe výletu rozhoduje rodič. Plán navrhuje poradie zastávok a čas prehliadky; vy volíte, kedy vyraziť, vypnete zastávky, ktoré dnes vynecháte, a zostanete dlhšie tam, kde sa deťom páči.'),
  ('home.about_p3', 'hr', 'O konačnom obliku izleta odlučuje roditelj. Plan predlaže redoslijed postaja i vrijeme razgledavanja; vi birate kada krenuti, isključujete postaje koje danas preskačete i ostajete dulje ondje gdje se djeci sviđa.'),
  ('home.about_p3', 'hu', 'A kirándulás végső formájáról a szülő dönt. A terv javasolja a megállók sorrendjét és a látogatás idejét; te választod ki, mikor induljatok, kikapcsolod a ma kihagyott megállókat, és tovább maradtok ott, ahol a gyerekek jól érzik magukat.'),
  ('home.about_p3', 'ro', 'Părintele decide forma finală a excursiei. Planul sugerează ordinea opririlor și timpul de vizitare; tu alegi când porniți, dezactivezi opririle pe care azi le săriți și rămâneți mai mult acolo unde copiilor le place.'),
  ('home.about_p3', 'sv', 'Föräldern bestämmer utflyktens slutliga form. Planen föreslår ordningen på stoppen och besökstiden; du väljer när ni börjar, stänger av stopp ni hoppar över i dag och stannar längre där barnen trivs.'),
  ('home.about_p3', 'da', 'Forælderen bestemmer turens endelige form. Planen foreslår rækkefølgen af stop og besøgstiden; du vælger, hvornår I starter, slår de stop fra, I springer over i dag, og bliver længere, hvor børnene hygger sig.'),
  ('home.about_p3', 'no', 'Forelderen bestemmer turens endelige form. Planen foreslår rekkefølgen på stoppene og besøkstiden; du velger når dere starter, slår av stopp dere hopper over i dag, og blir lenger der barna trives.'),
  ('home.about_p3', 'uk', 'Остаточну форму поїздки визначають батьки. План пропонує порядок зупинок і час огляду; ви обираєте, коли вирушати, вимикаєте зупинки, які сьогодні пропускаєте, і залишаєтеся довше там, де дітям подобається.'),
  ('home.how2_s1_x', 'pl', 'Plan dnia od parkingu po ostatni przystanek: przystanki po kolei, czas zwiedzania, godziny otwarcia i mapa trasy, którą przybliżysz palcami. Jeden przycisk otwiera całą trasę w Google Maps.'),
  ('home.how2_s1_x', 'en', 'A day plan from the car park to the last stop: stops in order, visiting time, opening hours and a route map you can zoom with your fingers. One button opens the whole route in Google Maps.'),
  ('home.how2_s6_t', 'pl', 'Ostatnia misja, miasto w albumie'),
  ('home.how2_s6_t', 'en', 'Last mission, the town goes into your album'),
  ('home.how2_s6_x', 'pl', 'Po ostatnim przystanku zdobyte miasto trafia do albumu rodziny, gdzie zbieracie kolejne wyprawy.'),
  ('home.how2_s6_x', 'en', 'After the last stop, the conquered town goes into your family album, where you collect your trips.'),
  ('home.subtitle', 'pl', 'Gotowe plany wycieczek jednodniowych po miastach Europy: gdzie zaparkować, co zobaczyć godzina po godzinie i jaką misję dostaje dziecko na każdym przystanku.'),
  ('home.subtitle', 'en', 'Ready-made day-trip plans for European cities: where to park, what to see hour by hour and what mission your child gets at each stop.'),
  ('home.subtitle', 'de', 'Fertige Tagesausflugspläne für Städte in Europa: wo man parkt, was man Stunde für Stunde sieht und welche Mission dein Kind an jeder Station bekommt.'),
  ('home.subtitle', 'it', 'Piani pronti per gite di un giorno nelle città d''Europa: dove parcheggiare, cosa vedere ora per ora e quale missione riceve il bambino a ogni tappa.'),
  ('home.subtitle', 'fr', 'Des plans d''excursion d''une journée prêts pour les villes d''Europe : où se garer, que voir heure par heure et quelle mission votre enfant reçoit à chaque étape.'),
  ('home.subtitle', 'es', 'Planes listos de excursiones de un día por ciudades de Europa: dónde aparcar, qué ver hora a hora y qué misión recibe tu hijo en cada parada.'),
  ('home.subtitle', 'pt', 'Planos prontos de passeios de um dia por cidades da Europa: onde estacionar, o que ver hora a hora e que missão a criança recebe em cada paragem.'),
  ('home.subtitle', 'nl', 'Kant-en-klare dagtochtplannen voor Europese steden: waar je parkeert, wat je uur voor uur ziet en welke missie je kind bij elke stop krijgt.'),
  ('home.subtitle', 'cs', 'Hotové plány jednodenních výletů po evropských městech: kde zaparkovat, co vidět hodinu po hodině a jakou misi dostane dítě na každé zastávce.'),
  ('home.subtitle', 'sk', 'Hotové plány jednodňových výletov po európskych mestách: kde zaparkovať, čo vidieť hodinu po hodine a akú misiu dostane dieťa na každej zastávke.'),
  ('home.subtitle', 'hr', 'Gotovi planovi jednodnevnih izleta po europskim gradovima: gdje parkirati, što vidjeti sat po sat i koju misiju dijete dobiva na svakoj postaji.'),
  ('home.subtitle', 'hu', 'Kész egynapos kirándulási tervek Európa városaiba: hol parkolj, mit nézz meg óráról órára, és milyen küldetést kap a gyerek minden megállónál.'),
  ('home.subtitle', 'ro', 'Planuri gata făcute de excursii de o zi prin orașele Europei: unde parchezi, ce vezi oră cu oră și ce misiune primește copilul la fiecare oprire.'),
  ('home.subtitle', 'sv', 'Färdiga planer för dagsutflykter i Europas städer: var ni parkerar, vad ni ser timme för timme och vilket uppdrag barnet får vid varje stopp.'),
  ('home.subtitle', 'da', 'Færdige planer for endagsture i Europas byer: hvor I parkerer, hvad I skal se time for time, og hvilken mission barnet får ved hvert stop.'),
  ('home.subtitle', 'no', 'Ferdige planer for dagsturer i Europas byer: hvor dere parkerer, hva dere ser time for time og hvilket oppdrag barnet får ved hvert stopp.'),
  ('home.subtitle', 'uk', 'Готові плани одноденних поїздок містами Європи: де припаркуватися, що подивитися година за годиною і яку місію отримує дитина на кожній зупинці.'),
  ('home.what_li6', 'pl', 'Ostateczny kształt trasy ustala rodzic: wyłączasz przystanki, które dziś pomijacie'),
  ('home.what_li6', 'en', 'The parent shapes the final route: switch off the stops you are skipping today'),
  ('home.what_li6', 'de', 'Die Eltern bestimmen die endgültige Route: Stationen, die ihr heute auslasst, schaltet ihr ab'),
  ('home.what_li6', 'it', 'Il percorso finale lo decide il genitore: disattivi le tappe che oggi saltate'),
  ('home.what_li6', 'fr', 'Le parent décide de l''itinéraire final : vous désactivez les étapes que vous sautez aujourd''hui'),
  ('home.what_li6', 'es', 'La ruta final la deciden los padres: desactivas las paradas que hoy os saltáis'),
  ('home.what_li6', 'pt', 'Os pais decidem o percurso final: desativa as paragens que hoje vão saltar'),
  ('home.what_li6', 'nl', 'De ouder bepaalt de uiteindelijke route: zet de stops uit die jullie vandaag overslaan'),
  ('home.what_li6', 'cs', 'Konečnou podobu trasy určuje rodič: vypnete zastávky, které dnes vynecháte'),
  ('home.what_li6', 'sk', 'Konečnú podobu trasy určuje rodič: vypnete zastávky, ktoré dnes vynecháte'),
  ('home.what_li6', 'hr', 'Konačan oblik rute određuje roditelj: isključite postaje koje danas preskačete'),
  ('home.what_li6', 'hu', 'Az útvonal végső formáját a szülő dönti el: kikapcsolod a ma kihagyott megállókat'),
  ('home.what_li6', 'ro', 'Traseul final îl decide părintele: dezactivezi opririle pe care azi le săriți'),
  ('home.what_li6', 'sv', 'Föräldern bestämmer den slutliga rutten: stäng av stopp ni hoppar över i dag'),
  ('home.what_li6', 'da', 'Forælderen bestemmer den endelige rute: slå de stop fra, I springer over i dag'),
  ('home.what_li6', 'no', 'Forelderen bestemmer den endelige ruten: slå av stopp dere hopper over i dag'),
  ('home.what_li6', 'uk', 'Остаточний маршрут визначають батьки: вимкніть зупинки, які сьогодні пропускаєте'),
  ('filter.half_day', 'pl', 'Pół dnia')
